package com.aistock.prediction.portfolioquestion;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import com.fasterxml.jackson.databind.node.*;import static com.aistock.prediction.portfolioquestion.QuestionEvidence.*;
class PortfolioQuestionFactsTest {
 @Test void whitelistRetainsSavedAmountsButNeverRawQuantityCostOrIdentity(){var f=PortfolioQuestionFacts.build(saved(),"解释盈亏","test-model",M);assertEquals("500.00",f.values().get("S0001_PROFIT"));assertEquals("SH600030",f.values().get("S0001_CODE"));assertFalse(f.values().toString().contains("20.000000"));assertFalse(f.values().keySet().stream().anyMatch(k->k.contains("QUANTITY")||k.contains("AVERAGE_COST")||k.contains("OWNER")));assertEquals(64,f.contextHash().length());assertEquals(f.contextHash(),PortfolioQuestionFacts.build(saved(),"解释盈亏","test-model",M).contextHash());assertNotEquals(f.contextHash(),PortfolioQuestionFacts.build(saved(),"解释盈亏","other-model",M).contextHash());}
 @Test void partialMixedAndUnknownAllRetainIndependentLimitations(){var f=PortfolioQuestionFacts.build(partial(),"解释限制","test-model",M);assertTrue(f.values().get("COVERAGE_LIMIT").contains("可估值部分"));assertTrue(f.values().get("DATE_LIMIT").contains("不同"));assertTrue(f.values().get("FRESHNESS_LIMIT").contains("无法确认"));assertFalse(f.values().containsKey("TOTAL_MARKET"));assertTrue(f.values().keySet().stream().noneMatch(k->k.endsWith("WEIGHT")||k.endsWith("CONCENTRATION")));}
 @Test void unavailableCompleteTotalsAndInvalidDatesFailClosed(){var n=saved();n.putNull("totals");assertThrows(Exception.class,()->PortfolioQuestionFacts.build(n,"解释","m",M));var future=saved();((ObjectNode)future.path("lines").get(0).path("quote")).put("priceDate","2026-10-20");assertThrows(Exception.class,()->PortfolioQuestionFacts.build(future,"解释","m",M));}
 @Test void noValuedPositionsCannotBeSentToAi(){var n=saved();n.put("valuedCount",0);assertThrows(Exception.class,()->PortfolioQuestionFacts.build(n,"解释","m",M));var empty=saved();empty.put("state","EMPTY").put("positionCount",0).put("valuedCount",0).putNull("totals").putArray("lines");assertThrows(Exception.class,()->PortfolioQuestionFacts.build(empty,"解释","m",M));}
 @Test void zeroCostNeverBecomesZeroPercentAndStaleIsExplicit(){var n=saved();((ObjectNode)n.path("lines").get(0)).putNull("returnPercent");((ObjectNode)n.path("totals")).putNull("returnPercent");((ObjectNode)n.path("subtotal")).putNull("returnPercent");n.put("freshness","STALE");((ObjectNode)n.path("lines").get(0).path("quote")).put("freshness","STALE");var f=PortfolioQuestionFacts.build(n,"收益率","m",M);assertTrue(f.values().get("S0001_RETURN").contains("无法计算"));assertTrue(f.values().get("FRESHNESS_LIMIT").contains("旧"));}
 @Test void configuredFactAndByteBudgetsRejectRatherThanTruncate(){assertThrows(Exception.class,()->PortfolioQuestionFacts.build(saved(),"解释","m",M,5,98304));assertThrows(Exception.class,()->PortfolioQuestionFacts.build(saved(),"解释","m",M,1800,20));}
 @Test void oneHundredSavedLinesAreAllRetainedAndExcessRejected(){var n=saved();var first=n.path("lines").get(0).deepCopy();var lines=n.putArray("lines");for(int i=0;i<100;i++){var l=(ObjectNode)first.deepCopy();String code=String.format(java.util.Locale.ROOT,"SH%06d",i);l.put("instrumentId",code).put("positionId",java.util.UUID.nameUUIDFromBytes(code.getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString()).put("weightPercent","1.00").put("concentrationTriggered",false);((ObjectNode)l.path("quote")).put("instrumentId",code);lines.add(l);}n.put("positionCount",100).put("valuedCount",100);for(String k:java.util.List.of("subtotal","totals"))((ObjectNode)n.path(k)).put("costAmount","200000.00").put("marketValue","250000.00").put("floatingProfit","50000.00");var f=PortfolioQuestionFacts.build(n,"解释","m",M);assertEquals("SH000099",f.values().get("S0100_CODE"));assertEquals(100,f.values().keySet().stream().filter(k->k.endsWith("_CODE")).count());n.put("positionCount",101);assertThrows(Exception.class,()->PortfolioQuestionFacts.build(n,"解释","m",M));}
}
